from concurrent.futures import ThreadPoolExecutor
from threading import Barrier, Condition, Lock
import time
import cachetools
from cachetools import cached, cachedmethod, LRUCache, func

def stampede(decorate, info=False):
    calls = []
    start = Barrier(12)
    @decorate
    def f(k):
        calls.append(k)
        time.sleep(.02)
        return object()
    def call(_):
        start.wait(timeout=3)
        return f(1)
    with ThreadPoolExecutor(12) as pool:
        results = list(pool.map(call, range(12)))
    assert len(calls) == 1
    assert all(r is results[0] for r in results)
    if info:
        assert f.cache_info()[:2] == (11, 1)
        f.cache_clear()
        assert f.cache_info()[:2] == (0, 0)
    return f
for info in (False, True):
    for cache in ({}, LRUCache(2)):
        c = Condition()
        f = stampede(cached(cache, condition=c, info=info), info)
        assert f.cache_lock is f.cache_condition is c
        lock = Lock()
        stampede(cached({}, lock=lock, condition=Condition(lock), info=info), info)
for decorator in (func.fifo_cache, func.lfu_cache, func.lru_cache, func.rr_cache, func.ttl_cache):
    for maxsize in (2, None):
        stampede(decorator(maxsize), True)
for info in (False, True):
    barrier = Barrier(2)
    @cached({}, condition=Condition(), info=info)
    def independent(k):
        barrier.wait(timeout=3)
        return k
    with ThreadPoolExecutor(2) as pool:
        assert list(pool.map(independent, (1, 2))) == [1, 2]
    for cache in ({}, LRUCache(0), None):
        calls = []
        @cached(cache, condition=Condition(), info=info)
        def f(k):
            calls.append(k)
            first = len(calls) == 1
            time.sleep(.001)
            if first:
                raise RuntimeError('first computation failed')
            return k
        def call(_):
            try:
                return f(1)
            except RuntimeError:
                return 'error'
        with ThreadPoolExecutor(8) as pool:
            results = list(pool.map(call, range(8)))
        assert results.count('error') == 1, results
        assert results.count(1) == 7
        f.cache_clear()
        assert f(1) == 1
class Instance:
    __hash__ = None
    def __init__(self):
        self.cache = {}
        self.cond = Condition()
        self.calls = 0
    @cachedmethod(lambda s: s.cache, condition=lambda s: s.cond)
    def f(self, k):
        self.calls += 1
        time.sleep(.02)
        return object()
for _ in range(3):
    obj = Instance()
    start = Barrier(12)
    def call(_):
        start.wait(timeout=3)
        return obj.f(1)
    with ThreadPoolExecutor(12) as pool:
        results = list(pool.map(call, range(12)))
    assert obj.calls == 1
    assert all(r is results[0] for r in results)
    assert obj.f.cache_condition(obj) is obj.cond
    assert obj.f.cache_lock(obj) is obj.cond
    obj.f.cache_clear(obj)
    assert not obj.cache
barrier = Barrier(2)
class Independent:
    def __init__(self):
        self.cache = {}
        self.cond = Condition()
    @cachedmethod(lambda s: s.cache, condition=lambda s: s.cond)
    def f(self, k):
        barrier.wait(timeout=3)
        return k
with ThreadPoolExecutor(2) as pool:
    assert list(pool.map(lambda o: o.f(1), [Independent(), Independent()])) == [1, 1]
class Direct:
    def __init__(self):
        self.cache = {}
    @cachedmethod(lambda s: s.cache, condition=Condition())
    def f(self, k):
        return k
assert Direct().f(1) == 1
assert not hasattr(cachetools, 'MRUCache')
assert not hasattr(func, 'mru_cache')
assert 'MRUCache' not in cachetools.__all__
assert 'mru_cache' not in func.__all__
print('All concurrency, exception recovery, statistics, independent key/instance, direct condition, and API removal checks passed')
